/* ════════════════════════════════════════════════════════════
   partiel_derives_qcm.js — QCM à choix unique de « Réviser le
   partiel » (7.7.0), lus par partiel_derives.html. Jamais dans
   BeQuick ni dans banque.js.

   Une question : id stable (q1-… Produits Dérivés I, q2-… Produits
   Dérivés II), th (thème), q (énoncé), o (quatre propositions : la
   PREMIÈRE est la bonne, la page mélange l’ordre), e (explication :
   pourquoi la bonne, où est le piège), eq (formule facultative, même
   notation courte que partiel_derives_donnees.js), calc (pour les
   mini-calculs : l’expression recalculée par le script de contrôle).
   Pour retirer une question : supprimer sa ligne.
   Programme de Produits Dérivés II : uniquement le TD Futures et le
   § 3.3.4 du cours (risques de la couverture, F comparé à f).
   ════════════════════════════════════════════════════════════ */
window.PARTIEL_QCM = {

/* ═════════════════ PRODUITS DÉRIVÉS I ═════════════════ */
pd1:[
/* — Le marché des changes — */
{id:'q1-001', th:'Le marché des changes', q:'Quelle place financière occupe le premier rang du marché des changes ?', o:['Londres', 'New York', 'Tokyo', 'Francfort'], e:'Londres traite plus de 30 % des transactions, devant New York (≈ 16 %) et Tokyo (≈ 9 %).'},
{id:'q1-002', th:'Le marché des changes', q:'L’USD intervient dans environ 88 % des transactions de change. Par rapport à quel total ce chiffre se lit-il ?', o:['200 %, car chaque transaction met en jeu deux monnaies', '100 %, comme toute part de marché', '50 %, car on ne compte que la devise achetée', '88 % est déjà un poids relatif, sans total'], e:'Une transaction met toujours deux monnaies en jeu : les parts s’additionnent jusqu’à 200 %. Le poids relatif réel de l’USD est donc d’environ 44 %.'},
{id:'q1-003', th:'Le marché des changes', q:'Quel est l’ordre de grandeur des transactions de change quotidiennes mondiales (BRI 2023) ?', o:['Environ 5 100 milliards de USD par jour', 'Environ 510 milliards de USD par jour', 'Environ 5 100 milliards de USD par an', 'Environ 51 000 milliards de USD par jour'], e:'Environ 5 100 milliards de dollars par jour selon la BRI (2023) : c’est le plus grand marché du monde.'},
{id:'q1-004', th:'Le marché des changes', q:'Le marché des changes « traditionnel » regroupe…', o:['le comptant (spot) et le terme (forward)', 'le comptant et les options de change', 'les Futures et les options', 'le terme et les swaps de taux'], e:'Marché traditionnel = comptant + terme, deux compartiments interdépendants. Futures et options sont des produits dérivés.'},
{id:'q1-005', th:'Le marché des changes', q:'Lequel de ces compartiments permet de couvrir le risque de change ?', o:['Le marché à terme', 'Le marché au comptant', 'Le change manuel', 'Le marché des billets'], e:'Seul le marché à terme fixe aujourd’hui un cours pour une livraison future : il permet la couverture.'},
{id:'q1-006', th:'Les participants', q:'Un courtier (broker) sur le marché des changes…', o:['est un intermédiaire qui ne prend aucune position de change', 'prend des positions pour son propre compte', 'fixe les cours de référence du marché', 'garantit la bonne fin des opérations'], e:'Le courtier met en relation et informe, sans jamais intervenir pour son propre compte. Les cours de référence viennent des market makers.'},
{id:'q1-007', th:'Les participants', q:'Quel est l’intérêt principal, pour un cambiste, de passer par un courtier ?', o:['Conserver l’anonymat jusqu’à la conclusion', 'Supprimer le risque de change', 'Payer moins que le spread de la banque', 'Obtenir un cours à terme garanti'], e:'Le nom de la contrepartie n’est révélé qu’une fois la transaction réalisée.'},
{id:'q1-008', th:'Les participants', q:'Les teneurs de marché (market makers)…', o:['affichent en permanence un cours acheteur et un cours vendeur', 'répondent uniquement aux demandes de leurs clients', 'n’interviennent que sur le marché de détail', 'sont des courtiers indépendants'], e:'Ils assurent la liquidité, servent de contrepartie et leurs cours font référence. Les cambistes clientèle (salers) répondent aux clients.'},
{id:'q1-009', th:'Les participants', q:'Pour être efficace, une intervention de banque centrale sur le marché des changes doit être…', o:['massive, coordonnée et opportune', 'discrète, isolée et progressive', 'annoncée à l’avance et limitée', 'réalisée uniquement à terme'], e:'Face à l’ampleur du marché, les réserves d’une banque centrale sont limitées : il faut frapper fort, à plusieurs et au bon moment.'},
{id:'q1-010', th:'Les participants', q:'Quelle part des transactions passe par les courtiers, et pour quelle commission ?', o:['Environ 40 %, commission de l’ordre de 0,01 %', 'Environ 10 %, commission de l’ordre de 1 %', 'Environ 80 %, sans commission', 'Environ 40 %, commission de l’ordre de 0,5 %'], e:'Environ 40 % des transactions, pour une commission de l’ordre de 0,01 %.'},
{id:'q1-011', th:'Fonctionnement', q:'Le compte nostri d’une banque française…', o:['est ouvert chez son correspondant étranger et tenu en devises', 'est ouvert chez elle par une banque étrangère, en euros', 'enregistre indifféremment devises et euros', 'est tenu par la banque centrale'], e:'Nostri = « le nôtre chez eux », en devises. Lori = « le leur chez nous », en monnaie nationale. Aucun passage entre les deux.'},
{id:'q1-012', th:'Fonctionnement', q:'SWIFT est…', o:['un réseau de transmission des ordres entre banques, créé en 1977', 'un mode de paiement interbancaire', 'une chambre de compensation des devises', 'le marché organisé des changes'], e:'SWIFT transmet les messages : c’est un mode de transmission, pas un mode de paiement.'},
{id:'q1-013', th:'Fonctionnement', q:'Quel est le montant minimal d’une transaction sur le marché de gros ?', o:['1 million de USD', '100 000 USD', '10 millions de USD', '50 000 USD'], e:'Le marché interbancaire réunit 50 à 80 très grandes banques, pour 1 million de USD minimum par transaction.'},
{id:'q1-014', th:'Fonctionnement', q:'Le marché des changes est un marché…', o:['de gré à gré, délocalisé, sans bourse centrale', 'organisé, avec une chambre de compensation', 'réglementé par la BCE', 'ouvert uniquement aux heures de Londres'], e:'OTC : rien n’est officiellement standardisé et tout se passe entre salles de marché. Il cote pratiquement 24 h sur 24, 5 jours sur 7.'},
{id:'q1-015', th:'Fonctionnement', q:'Un ordre « à cours limité » donné par un client fixe…', o:['un cours minimum de vente ou maximum d’achat', 'le premier cours coté disponible', 'un cours moyen de la journée', 'le cours de clôture'], e:'« Au mieux » = premier cours coté ; « à cours limité » = le client fixe une limite.'},
{id:'q1-016', th:'Fonctionnement', q:'Dans une salle des marchés, le middle office est chargé…', o:['des contrôles', 'de la relation avec les clients', 'de la comptabilité et de l’administratif', 'de la cotation des devises'], e:'Front office : cambistes ; middle office : contrôles ; back office : fonctions administratives et comptables.'},

/* — Les opérations — */
{id:'q1-017', th:'Couverture, spéculation, arbitrage', q:'Quand une entreprise se couvre, le risque de change…', o:['est transféré à un autre agent qui accepte de le prendre', 'disparaît du marché', 'est absorbé par la banque centrale', 'est partagé à parts égales avec la banque'], e:'Le risque ne disparaît pas : il change de porteur, contre l’espérance d’un gain.'},
{id:'q1-018', th:'Couverture, spéculation, arbitrage', q:'Quelle opération procure un gain sans risque en exploitant des écarts de cours au même moment ?', o:['L’arbitrage', 'La spéculation', 'La couverture', 'Le carry trade'], e:'L’arbitrage achète au plus bas et revend instantanément au plus haut. En se multipliant, il élimine les écarts.'},
{id:'q1-019', th:'Couverture, spéculation, arbitrage', q:'Un spéculateur qui prend une position de quelques minutes est un…', o:['scalper', 'day-to-day trader', 'long term trader', 'market maker'], e:'Quelques minutes : scalpers ; un jour : day-to-day traders ; plus long : long term traders.'},
{id:'q1-020', th:'Couverture, spéculation, arbitrage', q:'Pourquoi subsiste-t-il de petits écarts de cours non arbitrés ?', o:['Les coûts de transaction dépassent le gain possible', 'L’arbitrage est interdit sur ces devises', 'Les banques centrales les maintiennent', 'Les cours sont fixés une fois par jour'], e:'Le gain serait trop faible pour couvrir les coûts : l’écart reste.'},
{id:'q1-021', th:'Couverture, spéculation, arbitrage', q:'Une entreprise couverte à terme profite-t-elle d’une évolution favorable du cours ?', o:['Non : l’engagement est ferme, elle renonce au gain', 'Oui : la banque lui reverse la différence', 'Oui, si elle annule le contrat sans frais', 'Seulement pour la moitié du montant'], e:'Le terme sec fige le cours dans les deux sens : c’est le prix de la certitude.'},

/* — Lire un cours — */
{id:'q1-022', th:'Lire un cours', q:'GBP/USD = 1,6317 signifie que…', o:['1 GBP vaut 1,6317 USD', '1 USD vaut 1,6317 GBP', '1,6317 GBP valent 1 USD', '1 GBP vaut 1/1,6317 USD'], e:'A/B = nombre d’unités de B pour une unité de A : la devise de gauche est celle qu’on cote.'},
{id:'q1-023', th:'Lire un cours', q:'Sur le marché au comptant, la livraison des devises a lieu…', o:['au plus tard deux jours ouvrables après la transaction (J+2)', 'le jour même', 'à la fin du mois', 'cinq jours ouvrables après'], e:'Le cours est fixé le jour même, la livraison intervient à J+2 ouvrables.'},
{id:'q1-024', th:'Lire un cours', q:'Dans le code ISO 4217 « CHF », que désignent les deux premières lettres ?', o:['Le pays (Confoederatio Helvetica)', 'La devise (franc)', 'La banque centrale', 'La place de cotation'], e:'Deux lettres pour le pays, une pour la devise. L’EUR est l’exception.'},
{id:'q1-025', th:'Lire un cours', q:'Un tableau cote le CHF « pour 10 unités » à 9,1924 EUR. Combien vaut 1 CHF ?', o:['0,91924 EUR', '9,1924 EUR', '91,924 EUR', '1,0879 EUR'], e:'10 CHF valent 9,1924 EUR : on divise par 10. Oublier cette division est l’erreur numéro un des cours croisés.', calc:'9.1924/10'},
{id:'q1-026', th:'Lire un cours', q:'Le cours acheteur (bid) EUR/USD affiché par une banque est le prix auquel…', o:['la banque achète 1 EUR contre des USD', 'le client achète 1 EUR', 'la banque vend 1 EUR', 'la banque achète 1 USD contre des EUR'], e:'Les cours sont toujours ceux de la banque, et portent sur la devise de gauche. Le client qui vend des EUR reçoit le bid.'},
{id:'q1-027', th:'Lire un cours', q:'Dans une fourchette affichée par une banque…', o:['le cours vendeur est toujours supérieur au cours acheteur', 'le cours acheteur est toujours supérieur', 'les deux peuvent être égaux en temps normal', 'cela dépend de la devise'], e:'La banque achète bas et vend haut : l’écart est sa marge, le spread.'},
{id:'q1-028', th:'Lire un cours', q:'Dans USD/CHF = 0,9268, que représente « 0,92 » ?', o:['La figure', 'Les points', 'Le spread', 'Le pip'], e:'Partie entière + deux premières décimales = la figure ; le 4e chiffre est le point (pip).'},
{id:'q1-029', th:'Lire un cours', q:'USD/CHF = 0,9268 − 0,9280. Quel est le spread en points ?', o:['12 points', '1,2 point', '120 points', '0,12 point'], e:'0,9280 − 0,9268 = 0,0012, soit 12 points (un point = 0,0001).', calc:'(0.9280-0.9268)*1e4'},
{id:'q1-030', th:'Lire un cours', q:'USD/CHF = 0,9268 − 0,9280. Quel est le spread en pourcentage (convention du cours) ?', o:['0,13 %', '0,12 %', '1,29 %', '0,0013 %'], e:'On rapporte l’écart au cours acheteur : 0,0012 ÷ 0,9268 × 100 ≈ 0,13 %.', eq:'#t{spread} = #f{V − A}{A} × 100', calc:'(0.9280-0.9268)/0.9268*100'},
{id:'q1-031', th:'Lire un cours', q:'La cotation « 1,1470 − 75 » se lit…', o:['1,1470 acheteur et 1,1475 vendeur', '1,1470 acheteur et 1,1545 vendeur', '1,1470 moins 0,0075', '1,1475 acheteur et 1,1470 vendeur'], e:'Les deux derniers chiffres remplacent ceux du cours acheteur : 1,14|75.'},
{id:'q1-032', th:'Lire un cours', q:'Une banque cote USD/CHF 0,9273 − 0,9286 quand le marché est à 0,9268 − 0,9280. Que cherche-t-elle ?', o:['Acheter des USD : elle se constitue un stock', 'Vendre des USD au plus vite', 'Réduire son spread', 'Rien : c’est une erreur de saisie'], e:'Acheteur plus haut = elle veut acheter ; vendeur plus haut = elle ne veut pas vendre. Elle anticipe une hausse de l’USD.'},
{id:'q1-033', th:'Certain et incertain', q:'À Paris, « USD/EUR = 0,9093 » est une cotation…', o:['à l’incertain', 'au certain', 'croisée', 'à terme'], e:'Incertain : prix d’une unité de monnaie étrangère en monnaie locale (1 USD = 0,9093 EUR à Paris).'},
{id:'q1-034', th:'Certain et incertain', q:'Où la cotation au certain est-elle principalement pratiquée ?', o:['Grande-Bretagne, zone euro, Australie, Nouvelle-Zélande', 'États-Unis, Japon, Suisse', 'Chine et Inde', 'Partout, c’est la règle'], e:'Ailleurs, l’incertain domine.'},
{id:'q1-035', th:'Certain et incertain', q:'Pour une même devise à un instant donné, le produit de la cotation au certain et de la cotation à l’incertain vaut…', o:['1', '0', '100', 'le spread'], e:'Les deux cotations sont symétriques : (B/A) = 1 ÷ (A/B).'},
{id:'q1-036', th:'Certain et incertain', q:'En double cotation, le cours acheteur de B/A est égal à…', o:['1 ÷ (A/B) vendeur', '1 ÷ (A/B) acheteur', '(A/B) vendeur − (A/B) acheteur', '(A/B) acheteur × (A/B) vendeur'], e:'L’inversion croise les cours : c’est l’erreur classique en examen.', eq:'(B/A)^{A} = #f{1}{(A/B)^{V}}'},
{id:'q1-037', th:'Certain et incertain', q:'EUR/USD = 1,0850 − 1,0855. Quel est le cours acheteur USD/EUR ?', o:['0,9212', '0,9217', '1,0855', '0,9215'], e:'1 ÷ 1,0855 = 0,9212. Prendre 1 ÷ 1,0850 = 0,9217 donne le vendeur : piège classique.', calc:'1/1.0855'},
{id:'q1-038', th:'Certain et incertain', q:'EUR/USD = 1,1462 − 1,1466. Quel est le cours vendeur USD/EUR (4 décimales) ?', o:['0,8724', '0,8721', '0,8726', '1,1466'], e:'Vendeur USD/EUR = 1 ÷ acheteur EUR/USD = 1 ÷ 1,1462 ≈ 0,8724.', calc:'1/1.1462'},

/* — Conversions — */
{id:'q1-039', th:'Conversions', q:'Un exportateur français encaisse des USD et les vend à sa banque. EUR/USD = 1,1450 − 1,1456. Quel cours s’applique ?', o:['1,1456, on divise les USD', '1,1450, on divise les USD', '1,1456, on multiplie les USD', '1,1450, on multiplie les USD'], e:'Vendre des USD = acheter des EUR (devise de gauche) : la banque vend l’EUR, cours vendeur, et on divise pour obtenir des euros.'},
{id:'q1-040', th:'Conversions', q:'Un importateur français doit payer des USD. EUR/USD = 1,1450 − 1,1456. Quel cours s’applique ?', o:['1,1450 : la banque achète ses EUR', '1,1456 : la banque vend des EUR', '1,1453 : le cours moyen', '1 ÷ 1,1450'], e:'Acheter des USD = vendre des EUR : la banque achète l’EUR, cours acheteur. Coût en EUR = montant USD ÷ 1,1450.'},
{id:'q1-041', th:'Conversions', q:'3 500 000 USD encaissés, EUR/USD = 1,1462 − 1,1466. Combien d’EUR reçoit l’entreprise (à l’euro près) ?', o:['3 052 503 EUR', '3 053 568 EUR', '4 013 100 EUR', '4 011 700 EUR'], e:'3 500 000 ÷ 1,1466 ≈ 3 052 503 EUR. Diviser par 1,1462 favoriserait le client : la banque ne fait pas de cadeau.', calc:'3500000/1.1466'},
{id:'q1-042', th:'Conversions', q:'Test « anti-panique » quand on hésite entre les deux cours d’une fourchette :', o:['garder le résultat le moins favorable au client', 'garder le résultat le plus favorable au client', 'prendre la moyenne des deux', 'prendre toujours le cours acheteur'], e:'La banque ne fait jamais de cadeau : le bon cours est celui qui l’arrange.'},

/* — Cours croisés — */
{id:'q1-043', th:'Cours croisés', q:'EUR/USD et USD/JPY sont connus. Comment obtient-on EUR/JPY ?', o:['En multipliant : (EUR/USD) × (USD/JPY)', 'En divisant : (EUR/USD) ÷ (USD/JPY)', 'En additionnant les deux cours', 'En divisant : (USD/JPY) ÷ (EUR/USD)'], e:'Les cotations s’enchaînent par le pivot USD, qui « s’annule » : on multiplie.', eq:'(EUR/JPY) = (EUR/USD) × (USD/JPY)'},
{id:'q1-044', th:'Cours croisés', q:'Cours croisé en chaîne avec fourchettes : le cours acheteur A/B s’obtient par…', o:['acheteur × acheteur', 'acheteur × vendeur', 'vendeur × vendeur', 'acheteur ÷ vendeur'], e:'(A/B)ᴬ = (A/C)ᴬ × (C/B)ᴬ et (A/B)ⱽ = (A/C)ⱽ × (C/B)ⱽ.'},
{id:'q1-045', th:'Cours croisés', q:'EUR/USD et GBP/USD sont connus (les deux contre le pivot USD). Le cours acheteur EUR/GBP vaut…', o:['(EUR/USD) acheteur ÷ (GBP/USD) vendeur', '(EUR/USD) acheteur ÷ (GBP/USD) acheteur', '(EUR/USD) acheteur × (GBP/USD) acheteur', '(GBP/USD) vendeur ÷ (EUR/USD) acheteur'], e:'Quand on divise, acheteur et vendeur se croisent au dénominateur.', eq:'(A/B)^{A} = #f{(A/C)^{A}}{(B/C)^{V}}'},
{id:'q1-046', th:'Cours croisés', q:'EUR/USD = 1,1500 − 1,1504 et USD/JPY = 149,20 − 149,26. Cours acheteur EUR/JPY croisé ?', o:['171,58', '171,7087', '171,65', '129,74'], e:'1,1500 × 149,20 = 171,58 (acheteur × acheteur).', calc:'1.15*149.20'},
{id:'q1-047', th:'Cours croisés', q:'Même données (1,1500 − 1,1504 et 149,20 − 149,26). Cours vendeur EUR/JPY croisé (4 décimales) ?', o:['171,7087', '171,58', '171,6440', '171,6490'], e:'1,1504 × 149,26 = 171,708704 (vendeur × vendeur).', calc:'1.1504*149.26'},
{id:'q1-048', th:'Cours croisés', q:'Pourquoi une banque française « fabrique »-t-elle un cours USD/CHF ?', o:['Parce qu’il n’est pas coté directement sur sa place : elle passe par une monnaie pivot', 'Pour éviter de payer le spread', 'Parce que la loi l’impose', 'Pour spéculer sur le franc suisse'], e:'Faute de cotation directe, on reconstitue le cours par deux cotations qui ont une devise en commun.'},
{id:'q1-049', th:'Cours croisés', q:'Un cours croisé obtenu par une monnaie pivot a un spread…', o:['plus large que chacune des deux cotations d’origine', 'plus étroit', 'égal au plus petit des deux', 'nul'], e:'On paie deux fois une fourchette : le croisé est plus large que chaque cotation directe.'},

/* — Arbitrages — */
{id:'q1-050', th:'Arbitrages', q:'Un arbitrage géographique entre deux banques n’est possible que si…', o:['l’acheteur de l’une dépasse le vendeur de l’autre', 'les deux cours acheteurs diffèrent', 'les deux spreads diffèrent', 'les deux cours vendeurs diffèrent'], e:'Il faut que les fourchettes ne se chevauchent pas : acheter au vendeur le plus bas, revendre à l’acheteur le plus haut.'},
{id:'q1-051', th:'Arbitrages', q:'Banque X : EUR/CHF 0,9447 − 0,9451. Banque Y : 0,9445 − 0,9455. Y a-t-il un arbitrage ?', o:['Non, les fourchettes se chevauchent', 'Oui : acheter chez Y à 0,9445, revendre chez X à 0,9447', 'Oui : acheter chez X à 0,9451, revendre chez Y à 0,9455', 'Oui, de 2 points'], e:'On achète au vendeur (0,9451 ou 0,9455), on revend à l’acheteur (0,9447 ou 0,9445) : toujours à perte. 0,9445 n’est pas un prix d’achat pour nous.'},
{id:'q1-052', th:'Arbitrages', q:'Banque X : USD/CHF 0,9300 − 0,9310. Banque Y : 0,9315 − 0,9325. Quelle opération d’arbitrage ?', o:['Acheter des USD chez X à 0,9310 et les revendre chez Y à 0,9315', 'Acheter chez Y à 0,9325 et revendre chez X à 0,9300', 'Acheter chez X à 0,9300 et revendre chez Y à 0,9325', 'Aucune'], e:'Le vendeur de X (0,9310) est sous l’acheteur de Y (0,9315) : gain de 5 points par USD.'},
{id:'q1-053', th:'Arbitrages', q:'Arbitrage triangulaire : 1 000 000 EUR vendus à Londres à 171,90 JPY, JPY changés en USD à 149,26, USD en EUR à 1,1504. Montant final (à l’euro près) ?', o:['1 001 114 EUR', '998 886 EUR', '1 000 000 EUR', '997 442 EUR'], e:'1 000 000 × 171,90 ÷ 149,26 ÷ 1,1504 ≈ 1 001 114 EUR : gain d’environ 1 114 EUR.', eq:'W_{f} = #f{1 000 000 × 171,90}{149,26 × 1,1504}', calc:'1e6*171.90/149.26/1.1504'},
{id:'q1-054', th:'Arbitrages', q:'Lors du retour d’un arbitrage triangulaire, quand on achète la devise de gauche d’une cotation, on…', o:['divise par le cours vendeur', 'multiplie par le cours acheteur', 'divise par le cours acheteur', 'multiplie par le cours vendeur'], e:'Acheter la devise de gauche : la banque la vend, cours vendeur ; on paie en devise de droite, donc on divise.'},
{id:'q1-055', th:'Arbitrages', q:'Un arbitrage rapporte R = 1,001114 fois la mise. Une commission de x % est prise sur chacune des 3 conversions. Commission maximale ?', o:['1 − (1 ÷ R)^(1/3) ≈ 0,0371 %', '(R − 1) × 100 ≈ 0,1114 %', '3 × (R − 1) × 100 ≈ 0,3342 %', '(1 − 1 ÷ R)^3 × 100 ≈ 0,0000 %'], e:'La commission se multiplie trois fois : R × (1 − x)³ = 1, donc 1 − x est la racine cubique de 1 ÷ R. Piège : prendre tout le gain (0,1114 %) comme commission maximale par transaction.', eq:'x_{max} = 1 − #r3{#f{1}{R}}'},
{id:'q1-056', th:'Arbitrages', q:'En se multipliant, les arbitrages…', o:['font disparaître les écarts de cours entre places', 'creusent les écarts', 'augmentent les spreads', 'n’ont aucun effet sur les cours'], e:'Acheter là où c’est bas fait monter le prix, vendre là où c’est haut le fait baisser : convergence des cours.'},
{id:'q1-057', th:'Arbitrages', q:'Le « bid critique » d’une banque, en dessous duquel l’arbitrage triangulaire disparaît, est égal…', o:['au cours vendeur croisé de l’autre circuit', 'au cours acheteur croisé de l’autre circuit', 'au milieu de fourchette', 'à son propre cours vendeur'], e:'On vend l’EUR à son bid et on le rachète au vendeur croisé : l’arbitrage cesse quand les deux sont égaux.'},

/* — Le marché à terme — */
{id:'q1-058', th:'Le marché à terme', q:'Dans un contrat de change à terme, qu’est-ce qui est fixé le jour de l’accord ?', o:['La quantité, le cours et l’échéance', 'Seulement la quantité', 'La quantité et l’échéance, le cours à l’échéance', 'Seulement le cours'], e:'Tout est fixé immédiatement ; seuls les mouvements de fonds attendent l’échéance.'},
{id:'q1-059', th:'Le marché à terme', q:'Le dénouement effectif d’une opération de change à terme a lieu…', o:['le deuxième jour ouvrable après l’échéance (J+2)', 'le jour de la négociation', 'le jour de l’échéance exactement', 'à la fin du mois de l’échéance'], e:'Comme au comptant, la livraison se fait à J+2 ouvrables, mais après l’échéance.'},
{id:'q1-060', th:'Le marché à terme', q:'Une échéance « brisée » (qui n’est pas un nombre de mois exact)…', o:['est possible mais plus coûteuse', 'est interdite', 'est gratuite', 'n’existe que pour l’USD'], e:'Le banquier couvre plus difficilement son propre risque : il le fait payer.'},
{id:'q1-061', th:'Le marché à terme', q:'Les deux segments du marché à terme sont…', o:['le terme sec et le swap de change', 'le comptant et le terme', 'les Futures et les options', 'le terme sec et le marché monétaire'], e:'Terme sec (forward outright) et swap de change ; le cours traite le terme sec.'},
{id:'q1-062', th:'Le marché à terme', q:'Pour coter à terme à un client, le cambiste combine…', o:['une opération de change au comptant et une opération de trésorerie (emprunt, placement)', 'deux opérations à terme', 'un achat de Futures et une option', 'un change au comptant seulement'], e:'Il fabrique le cours : emprunt, change au comptant, placement. Il se couvre lui-même.'},
{id:'q1-063', th:'Le marché à terme', q:'Le carry trade consiste à…', o:['emprunter dans une devise à faible taux pour placer dans une devise à taux plus élevé', 'acheter à terme une devise en déport', 'arbitrer entre deux places au comptant', 'couvrir une créance par un achat à terme'], e:'Son risque clé : la dépréciation de la devise de placement.'},

/* — Report, déport — */
{id:'q1-064', th:'Report et déport', q:'Une devise est en report quand…', o:['son cours à terme est supérieur à son cours au comptant', 'son cours à terme est inférieur au comptant', 'son taux d’intérêt est plus élevé', 'elle s’est appréciée au comptant'], e:'Report : f &gt; S. Déport : f &lt; S. Report et déport se disent de la devise de gauche.'},
{id:'q1-065', th:'Report et déport', q:'La devise dont le taux d’intérêt est le plus élevé est, à terme…', o:['en déport', 'en report', 'au pair', 'en report ou déport selon le spread'], e:'Le terme compense l’avantage de taux : la devise la mieux rémunérée vaut moins à terme.'},
{id:'q1-066', th:'Report et déport', q:'GBP/USD comptant 1,6312, à 1 mois 1,6317. La livre est…', o:['en report de 5 points', 'en déport de 5 points', 'en report de 0,5 point', 'en déport de 50 points'], e:'1,6317 − 1,6312 = +0,0005, soit 5 points de report.', calc:'(1.6317-1.6312)*1e4'},
{id:'q1-067', th:'Report et déport', q:'Taux de report annualisé : (1,6317 − 1,6312) ÷ 1,6312 × 12/1 × 100 vaut environ…', o:['+0,37 %', '+0,03 %', '+3,68 %', '−0,37 %'], e:'0,0005 ÷ 1,6312 ≈ 0,0307 % sur un mois, × 12 ≈ 0,37 % par an.', eq:'#t{taux} = #f{f − S}{S} × #f{12}{n} × 100', calc:'(1.6317-1.6312)/1.6312*12*100'},
{id:'q1-068', th:'Report et déport', q:'EUR/CHF comptant 0,9400, à 6 mois 0,9317. Taux de déport annualisé ?', o:['−1,77 %', '−0,88 %', '−0,0083 %', '−17,7 %'], e:'(0,9317 − 0,9400) ÷ 0,9400 × 12/6 × 100 ≈ −1,77 %. Oublier d’annualiser donne −0,88 %.', calc:'(0.9317-0.94)/0.94*2*100'},
{id:'q1-069', th:'Report et déport', q:'Pour un cours à terme sur 90 jours, le taux de report s’annualise avec…', o:['360 ÷ 90', '365 ÷ 90', '12 ÷ 90', '90 ÷ 360'], e:'Convention du cours : durée en jours sur une base de 360 ; en mois, 12 ÷ n.'},

/* — Points de swap — */
{id:'q1-070', th:'Points de swap', q:'EUR/USD comptant 1,1470 − 75, points à 1 mois 10 − 15. Cours à terme ?', o:['1,1480 − 1,1490', '1,1460 − 1,1460', '1,1460 − 1,1475', '1,1570 − 1,1625'], e:'10 &lt; 15 : report, on additionne 0,0010 et 0,0015.'},
{id:'q1-071', th:'Points de swap', q:'USD/CHF comptant 1,6975 − 95, points à 1 mois 145 − 139. Cours à terme ?', o:['1,6830 − 1,6856', '1,7120 − 1,7134', '1,6830 − 1,6850', '1,6836 − 1,6850'], e:'145 &gt; 139 : déport, on soustrait : 1,6975 − 0,0145 et 1,6995 − 0,0139.'},
{id:'q1-072', th:'Points de swap', q:'Points de terme « 145 − 139 » (décroissants) signifient…', o:['un déport : on soustrait les points', 'un report : on additionne', 'une erreur de cotation', 'un spread négatif'], e:'Décroissants = déport. Contrôle : le spread doit s’élargir à terme.'},
{id:'q1-073', th:'Points de swap', q:'Quel contrôle permet de vérifier le sens des points de swap ?', o:['Le spread à terme doit être plus large qu’au comptant', 'Le cours à terme doit dépasser le comptant', 'Les points doivent être positifs', 'Le spread à terme doit être plus étroit'], e:'Plus l’échéance est lointaine, plus la fourchette s’élargit.'},
{id:'q1-074', th:'Points de swap', q:'EUR/CHF comptant 0,9400 − 0,9406, à 6 mois 0,9317 − 0,9360. Points de swap acheteurs ?', o:['−83 points', '−46 points', '+83 points', '−89 points'], e:'0,9317 − 0,9400 = −0,0083, soit −83 points (acheteur avec acheteur).', calc:'(0.9317-0.94)*1e4'},

/* — Eurodevises — */
{id:'q1-075', th:'Eurodevises', q:'Un dollar déposé dans une banque à New York est-il un eurodollar ?', o:['Non : il est dans son pays d’émission', 'Oui, si le déposant est européen', 'Oui, si la banque est européenne', 'Oui, dès qu’il sert au commerce international'], e:'Seule compte la localisation du dépôt, jamais la nationalité du déposant ou de la banque.'},
{id:'q1-076', th:'Eurodevises', q:'Dans la cotation « 1 3/4 − 1 7/8 » d’une banque, à quel taux la banque prête-t-elle ?', o:['1,875 %', '1,75 %', '1,8125 %', '0,125 %'], e:'Le premier taux est celui auquel la banque emprunte, le second celui auquel elle prête.'},
{id:'q1-077', th:'Eurodevises', q:'« 2 5/16 − 2 7/16 » : que vaut le taux emprunteur ?', o:['2,3125 %', '2,4375 %', '2,5 %', '2,0625 %'], e:'2 + 5/16 = 2,3125 %. Le second (2,4375 %) est le prêteur.', calc:'2+5/16'},
{id:'q1-078', th:'Eurodevises', q:'Taux prêteur 4 7/8 % et spread de 1/8 % : taux emprunteur ?', o:['4,75 %', '5 %', '4,875 %', '4,625 %'], e:'Emprunteur = prêteur − spread = 4,875 − 0,125 = 4,75 %.', calc:'4.875-0.125'},
{id:'q1-079', th:'Eurodevises', q:'Une entreprise place 20 M CHF auprès de sa banque, cotation CHF 2 − 2 1/2. Quel taux obtient-elle ?', o:['2 %', '2,5 %', '2,25 %', '0,5 %'], e:'Elle prête à la banque : elle reçoit le taux emprunteur de la banque, le plus bas.'},
{id:'q1-080', th:'Eurodevises', q:'Pourquoi les taux des eurodevises sont-ils plus compétitifs que ceux du marché local ?', o:['Pas de réserves obligatoires ni de plafond de rémunération, et économies d’échelle', 'Ils sont garantis par la banque centrale', 'Ils ne comportent aucun risque', 'Ils sont fixés par la BRI'], e:'Les euro-banques échappent aux contraintes nationales ; en contrepartie le risque de non-remboursement est réel.'},
{id:'q1-081', th:'Eurodevises', q:'Le spread de taux sur le marché des eurodevises va de…', o:['1/8 % à 2 %', '1/32 % à 1/16 %', '2 % à 5 %', '0 à 1/8 %'], e:'De 1/8 % jusqu’à 2 % ; taux écrits en général en multiples de 1/32.'},

/* — Position et risque de change — */
{id:'q1-082', th:'Position de change', q:'Position de change = …', o:['créances en devises − dettes en devises, par devise et par échéance', 'dettes − créances, toutes devises confondues', 'créances + dettes', 'créances en devises − dettes en euros'], e:'Pas de compensation entre devises ni entre échéances différentes.'},
{id:'q1-083', th:'Position de change', q:'Créances 800 000 USD, dettes 500 000 USD à 3 mois. Position et risque ?', o:['Longue de 300 000 USD : risque de baisse de l’USD', 'Courte de 300 000 USD : risque de hausse de l’USD', 'Longue de 300 000 USD : risque de hausse de l’USD', 'Fermée : pas de risque'], e:'Créances &gt; dettes : position longue, on craint la baisse de la devise. Couverture : vente à terme.'},
{id:'q1-084', th:'Position de change', q:'Une entreprise importatrice est typiquement en position…', o:['courte, avec un risque de hausse de la devise', 'longue, avec un risque de baisse', 'fermée', 'longue, avec un risque de hausse'], e:'Dettes en devises : une hausse du cours alourdit le décaissement.'},
{id:'q1-085', th:'Position de change', q:'Un exportateur français facture en euros. Est-il exposé au risque de change ?', o:['Non : la transaction n’est pas libellée en devises', 'Oui, dès qu’il vend à l’étranger', 'Oui, si le paiement est à crédit', 'Oui, pour la moitié du montant'], e:'Les trois conditions sont cumulatives : étranger, devises, décalage dans le temps. Ici c’est le client étranger qui porte le risque.'},
{id:'q1-086', th:'Position de change', q:'Créance de 50 000 USD au 1er avril, dette de 50 000 USD au 1er juillet. Position ?', o:['Deux positions ouvertes : longue en avril, courte en juillet', 'Position fermée', 'Position longue de 100 000 USD', 'Position nulle car même devise'], e:'On ne compense pas des échéances différentes.'},
{id:'q1-087', th:'Position de change', q:'LVMH : créances 2 500 000 GBP, dettes 3 400 000 GBP à 3 mois. Couverture ?', o:['Acheter 900 000 GBP à terme', 'Vendre 900 000 GBP à terme', 'Acheter 3 400 000 GBP à terme', 'Aucune : les montants se compensent'], e:'Position courte de 900 000 GBP : on craint la hausse de la livre, on l’achète à terme.', calc:'2500000-3400000'},
{id:'q1-088', th:'Position de change', q:'Couvrir une position nette plutôt que créance et dette séparément…', o:['évite de payer deux fois la fourchette sur la partie qui se compense', 'supprime tout risque de contrepartie', 'coûte plus cher', 'est interdit si les montants diffèrent'], e:'Ex. Nestlé : 1 800 000 EUR se compensent ; deux contrats séparés feraient vendre à 0,9317 et racheter à 0,9360.'},

/* — Cours à terme acheteur et vendeur — */
{id:'q1-089', th:'Cours à terme fabriqué', q:'Pour construire son cours à terme acheteur A/B, la banque…', o:['emprunte A, vend A au comptant contre B, place B', 'emprunte B, achète A au comptant, place A', 'achète A à terme sur le marché', 'emprunte A et B en même temps'], e:'Elle achètera A à terme : elle doit s’en défaire aujourd’hui sans en avoir, donc elle l’emprunte et le vend.'},
{id:'q1-090', th:'Cours à terme fabriqué', q:'Formule du cours à terme acheteur A/B (n en mois) :', o:['Sᴬ × (1 + r_B emprunteur × n/12) ÷ (1 + r_A prêteur × n/12)', 'Sᴬ × (1 + r_A prêteur × n/12) ÷ (1 + r_B emprunteur × n/12)', 'Sⱽ × (1 + r_B prêteur × n/12) ÷ (1 + r_A emprunteur × n/12)', 'Sᴬ × (1 + r_B prêteur × n/12) ÷ (1 + r_A emprunteur × n/12)'], e:'Comptant acheteur ; au numérateur le placement de B (taux emprunteur), au dénominateur l’emprunt de A (taux prêteur).', eq:'f^{A} = S^{A} × #f{1 + r^{emp}_{B} × #f{n}{12}}{1 + r^{prêt}_{A} × #f{n}{12}}'},
{id:'q1-091', th:'Cours à terme fabriqué', q:'Le cours à terme vendeur sert surtout…', o:['à l’importateur, qui doit acheter la devise à terme', 'à l’exportateur, qui vend la devise à terme', 'au spéculateur à la baisse', 'à la banque centrale'], e:'La banque vend la devise à terme à un client qui doit la payer plus tard : l’importateur.'},
{id:'q1-092', th:'Cours à terme fabriqué', q:'Une société suisse (comptes en CHF) a une créance en EUR à 6 mois. EUR/CHF : quel cours à terme la banque applique-t-elle ?', o:['Le cours à terme acheteur EUR/CHF', 'Le cours à terme vendeur EUR/CHF', 'Le cours au comptant acheteur', 'La moyenne des deux cours à terme'], e:'La société vendra ses EUR : la banque les achète, cours acheteur.'},
{id:'q1-093', th:'Cours à terme fabriqué', q:'EUR/CHF acheteur 0,9400 ; taux CHF emprunteur 1 %, EUR prêteur 2,80 % ; 6 mois. Cours à terme acheteur (4 décimales) ?', o:['0,9317', '0,9483', '0,9360', '0,9353'], e:'0,9400 × (1 + 1 % × 6/12) ÷ (1 + 2,80 % × 6/12) ≈ 0,9317.', eq:'f^{A} = 0,9400 × #f{1 + 0,01 × #f{6}{12}}{1 + 0,028 × #f{6}{12}}', calc:'0.94*(1+0.01/2)/(1+0.028/2)'},
{id:'q1-094', th:'Cours à terme fabriqué', q:'Pour fabriquer un cours à terme, la banque emprunte sur le marché au…', o:['taux prêteur (le plus haut) et place au taux emprunteur (le plus bas)', 'taux emprunteur et place au taux prêteur', 'taux moyen dans les deux cas', 'taux de la banque centrale'], e:'Elle est preneuse sur le marché interbancaire : on emprunte cher, on place bas. C’est ce que reprennent les formules du cours.'},
{id:'q1-095', th:'Cours à terme fabriqué', q:'Sigma doit encaisser des SEK à 3 mois. Cotation EUR/SEK. Quel cours à terme ?', o:['Vendeur EUR/SEK : Sigma achète des EUR', 'Acheteur EUR/SEK : Sigma vend des SEK', 'Acheteur SEK/EUR', 'Le comptant, la créance étant courte'], e:'Piège : on raisonne sur la devise de gauche (EUR). Sigma l’achète, la banque la vend : cours vendeur.'},

/* — Parité des taux et placements — */
{id:'q1-096', th:'Parité des taux', q:'Selon la parité des taux couverte, le cours à terme théorique A/B vaut…', o:['S × (1 + r_B × n/12) ÷ (1 + r_A × n/12)', 'S × (1 + r_A × n/12) ÷ (1 + r_B × n/12)', 'S × (r_B − r_A)', 'S + (r_B − r_A)'], e:'Le taux de la monnaie de cotation (B, à droite) au numérateur.', eq:'f = S × #f{1 + r_{B} × #f{n}{12}}{1 + r_{A} × #f{n}{12}}'},
{id:'q1-097', th:'Parité des taux', q:'10 SEK = 0,9300 USD ; taux USD 2 %, SEK 4 % ; 6 mois. Cours à terme théorique pour 10 SEK ?', o:['0,9209', '0,9392', '0,9300', '0,9116'], e:'0,93 × 1,01 ÷ 1,02 ≈ 0,9209 : la couronne, mieux rémunérée, est en déport.', calc:'0.93*1.01/1.02'},
{id:'q1-098', th:'Parité des taux', q:'Le cours à terme coté (0,9350) est au-dessus du théorique (0,9209), en USD pour 10 SEK. Où vont les capitaux ?', o:['À Stockholm : placer en SEK couvert à terme rapporte plus', 'À New York', 'Nulle part : la parité tient', 'Vers la devise en déport, toujours'], e:'La couronne est trop chère à terme : la revendre à terme après un placement à 4 % bat le placement à 2 % à New York.'},
{id:'q1-099', th:'Parité des taux', q:'1 000 000 GBP, spot 1 USD = 0,68 GBP, forward 1 an 0,6874, taux USD 4 %. Placement couvert aux États-Unis ?', o:['1 051 317,65 GBP', '1 040 000,00 GBP', '1 060 000,00 GBP', '1 029 058,82 GBP'], e:'1 000 000 ÷ 0,68 × 1,04 × 0,6874 ≈ 1 051 317,65 GBP, moins que 1 060 000 à Londres.', calc:'1e6/0.68*1.04*0.6874'},
{id:'q1-100', th:'Parité des taux', q:'Si la parité des taux couverte est vérifiée…', o:['placer chez soi ou à l’étranger couvert à terme rapporte la même chose', 'la devise au taux le plus élevé est en report', 'le cours à terme est égal au comptant', 'un arbitrage est toujours possible'], e:'C’est la condition d’absence d’arbitrage : l’écart de taux est exactement compensé par le report ou le déport.'},
{id:'q1-101', th:'Parité des taux', q:'Placement couvert : dans quel ordre ?', o:['Change au comptant, placement, revente à terme fixée dès le départ', 'Placement, change au comptant à l’échéance', 'Revente à terme, puis change au comptant', 'Emprunt, placement, change au comptant à l’échéance'], e:'La revente à terme est conclue dès aujourd’hui : le résultat est certain.'},

/* — Couverture à terme — */
{id:'q1-102', th:'Couverture à terme', q:'Vente à terme de 4 800 000 USD, EUR/USD à 3 mois 1,1490 − 1,1498. Euros garantis (à l’euro près) ?', o:['4 174 639 EUR', '4 177 546 EUR', '5 515 200 EUR', '5 519 040 EUR'], e:'Vendre des USD = acheter des EUR, cours vendeur : 4 800 000 ÷ 1,1498.', calc:'4800000/1.1498'},
{id:'q1-103', th:'Couverture à terme', q:'LVMH a vendu ses USD à terme à 1,1498. À l’échéance, EUR/USD vaut 1,1908 (vendeur). La couverture a…', o:['rapporté : sans elle, LVMH aurait reçu moins d’euros', 'coûté : sans elle, LVMH aurait reçu plus d’euros', 'été neutre', 'été annulée'], e:'Le dollar a baissé (EUR/USD monte) : 4 800 000 ÷ 1,1908 &lt; 4 800 000 ÷ 1,1498.'},
{id:'q1-104', th:'Couverture à terme', q:'Le cours critique d’une couverture à terme d’une position longue en USD (cotation EUR/USD) est…', o:['le cours à terme lui-même : au-dessus, la couverture gagne', 'le cours au comptant du jour de la couverture', 'la moyenne entre comptant et terme', 'le cours qui annule le spread'], e:'Couvert ou non, le même montant en USD : l’égalité donne S* = f. Au-dessus (dollar plus faible), la couverture est gagnante.'},
{id:'q1-105', th:'Couverture à terme', q:'LVMH a vendu 4 800 000 USD à terme, puis un client annule 2 000 000 USD de créances. Position résiduelle à l’échéance ?', o:['Courte de 2 000 000 USD : il faudra en acheter au comptant', 'Longue de 2 000 000 USD', 'Fermée : le contrat est annulé d’office', 'Courte de 4 800 000 USD'], e:'Il recevra 2 800 000 USD mais doit en livrer 4 800 000 : le contrat à terme est un engagement ferme.', calc:'(8000000-2000000-3200000)-4800000'},
{id:'q1-106', th:'Couverture à terme', q:'Une entreprise française a une dette de 900 000 GBP à 3 mois. EUR/GBP à 3 mois 0,8668 − 0,8676. Coût garanti en EUR ?', o:['900 000 ÷ 0,8668 ≈ 1 038 302 EUR', '900 000 ÷ 0,8676 ≈ 1 037 344 EUR', '900 000 × 0,8668 = 780 120 EUR', '900 000 × 0,8676 = 780 840 EUR'], e:'Acheter des GBP = vendre des EUR : la banque achète l’EUR, cours acheteur, et on divise.', calc:'900000/0.8668'}
],

/* ═════════════════ PRODUITS DÉRIVÉS II ═════════════════
   Strictement : TD Futures (5 exercices) et § 3.3.4. */
pd2:[
/* — Lire un contrat — */
{id:'q2-001', th:'Le contrat Future', q:'Le contrat Future EUR/USD du CME a une taille standard de…', o:['125 000 EUR', '62 500 EUR', '100 000 USD', '125 000 USD'], e:'Données du TD : 125 000 EUR pour EUR/USD, 62 500 GBP pour GBP/USD.'},
{id:'q2-002', th:'Le contrat Future', q:'Le contrat Future GBP/USD utilisé dans le TD a une taille de…', o:['62 500 GBP', '125 000 GBP', '62 500 USD', '100 000 GBP'], e:'Exercices 1 et 5 : T = 62 500 GBP.'},
{id:'q2-003', th:'Le contrat Future', q:'Le contrat EUR/USD est coté…', o:['en USD pour 1 EUR', 'en EUR pour 1 USD', 'en points de swap', 'en pourcentage'], e:'Cours = nombre de dollars pour un euro, comme la cotation EUR/USD.'},
{id:'q2-004', th:'Le contrat Future', q:'Tick en valeur de 12,5 USD pour un contrat de 62 500 GBP : la variation minimale du cours est de…', o:['0,0002 USD par GBP', '0,0001 USD par GBP', '0,002 USD par GBP', '12,5 USD par GBP'], e:'Tick = 12,5 ÷ 62 500 = 0,0002.', eq:'#t{tick} = #f{V_{#t{tick}}}{T}', calc:'12.5/62500'},
{id:'q2-005', th:'Le contrat Future', q:'Un cours passe de 1,5210 à 1,5200, avec un tick de 0,0002. Combien de ticks ?', o:['−5 ticks', '−10 ticks', '−50 ticks', '−1 tick'], e:'−0,0010 ÷ 0,0002 = −5 ticks.', calc:'(1.5200-1.5210)/0.0002'},
{id:'q2-006', th:'Le contrat Future', q:'Qui exige les dépôts de marge et procède aux appels et restitutions ?', o:['La chambre de compensation', 'Le courtier du client', 'La banque centrale', 'La contrepartie directe du client'], e:'TD, exercice 1 : appels et restitutions effectués par la chambre de compensation de l’IMM.'},
{id:'q2-007', th:'Le contrat Future', q:'L’acheteur d’un Future gagne quand…', o:['le cours du Future monte', 'le cours du Future baisse', 'la base augmente', 'le spot baisse'], e:'Résultat de l’acheteur = (F de vente − F d’achat) × T × N.'},
{id:'q2-008', th:'Le contrat Future', q:'Achat de 3 contrats EUR/USD à 1,0850, revente à 1,0910. Résultat ?', o:['+2 250 USD', '−2 250 USD', '+750 USD', '+2 250 EUR'], e:'(1,0910 − 1,0850) × 125 000 × 3 = +2 250 USD. Le résultat est en USD, la monnaie de cotation.', calc:'(1.0910-1.0850)*125000*3'},

/* — Marges — */
{id:'q2-009', th:'Les marges', q:'Le deposit initial est conçu pour couvrir…', o:['la perte maximale d’une journée', 'la perte totale jusqu’à l’échéance', 'la commission du courtier', 'la valeur notionnelle du contrat'], e:'Exercice 1 : deposit = limite quotidienne × tick en valeur × nombre de contrats.'},
{id:'q2-010', th:'Les marges', q:'15 contrats, tick en valeur 12,5 USD, limite quotidienne 50 ticks. Deposit ?', o:['9 375 USD', '625 USD', '7 500 USD', '187,5 USD'], e:'50 × 12,5 × 15 = 9 375 USD.', eq:'D = L × V_{#t{tick}} × N', calc:'50*12.5*15'},
{id:'q2-011', th:'Les marges', q:'Deposit 9 375 USD, maintenance 80 % du deposit. Marge de maintenance ?', o:['7 500 USD', '1 875 USD', '9 375 USD', '11 718,75 USD'], e:'0,80 × 9 375 = 7 500 USD.', calc:'0.8*9375'},
{id:'q2-012', th:'Les marges', q:'Quand y a-t-il appel de marge ?', o:['Quand le solde du compte passe sous la marge de maintenance', 'Dès que le solde passe sous le deposit', 'À chaque perte journalière', 'Seulement à l’échéance du contrat'], e:'La maintenance est le seuil de déclenchement.'},
{id:'q2-013', th:'Les marges', q:'Le montant d’un appel de marge ramène le compte…', o:['au deposit initial', 'à la marge de maintenance', 'à zéro', 'au solde de la veille'], e:'Piège classique : on reconstitue le deposit, pas la maintenance.', eq:'#t{Appel} = D − #t{Solde}'},
{id:'q2-014', th:'Les marges', q:'Deposit 9 375, maintenance 7 500. Le solde tombe à 1 500 USD. Appel ?', o:['7 875 USD', '6 000 USD', '1 500 USD', '9 375 USD'], e:'9 375 − 1 500 = 7 875 USD.', calc:'9375-1500'},
{id:'q2-015', th:'Les marges', q:'Deposit 16 000, maintenance 12 000. Le solde est de 15 500 USD le soir. Appel ?', o:['Aucun : 15 500 ≥ 12 000', '500 USD', '3 500 USD', '4 000 USD'], e:'Le solde reste au-dessus de la maintenance : pas d’appel, même s’il est sous le deposit.'},
{id:'q2-016', th:'Les marges', q:'« Mon deposit était de 16 000 USD et mon compte contient encore 6 000 USD (maintenance 12 000), je n’ai rien à verser. » ', o:['Faux : 6 000 &lt; 12 000, il faut verser 10 000 USD', 'Vrai : le compte est encore positif', 'Faux : il faut verser 6 000 USD', 'Faux : il faut verser 12 000 USD'], e:'Seuil : la maintenance (12 000). Montant : retour au deposit, 16 000 − 6 000 = 10 000.'},
{id:'q2-017', th:'Les marges', q:'Une restitution de marge correspond à…', o:['un gain du jour crédité sur le compte de marge', 'le remboursement des appels à l’échéance', 'une baisse du deposit exigé', 'une commission rendue par la chambre'], e:'Les gains sont crédités chaque soir ; dans le TD, ils restent sur le compte (pas de retrait).'},
{id:'q2-018', th:'Les marges', q:'Quand les restitutions ne font pas l’objet de retraits, un gain du jour…', o:['reste sur le compte et augmente le solde', 'est versé au client le soir même', 'réduit le deposit exigé', 'est perdu'], e:'Exercice 1 : le 08-01, +8 437,5 USD portent le solde à 17 812,5.'},
{id:'q2-019', th:'Les marges', q:'Le premier soir, le résultat du jour se calcule par rapport…', o:['au cours d’ouverture de la position', 'au cours de compensation de la veille du marché', 'au cours au comptant', 'au cours d’échéance'], e:'Ensuite, chaque jour se calcule par rapport au cours de compensation de la veille.'},
{id:'q2-020', th:'Les marges', q:'Acheteur de 15 contrats GBP (62 500), le cours passe de 1,5126 à 1,5030. Résultat du jour ?', o:['−9 000 USD', '+9 000 USD', '−600 USD', '−6 937,5 USD'], e:'(1,5030 − 1,5126) × 62 500 × 15 = −9 000 USD.', calc:'(1.5030-1.5126)*62500*15'},
{id:'q2-021', th:'Les marges', q:'Vendeur de 5 contrats EUR/USD à 1,1500, compensation du soir à 1,1540. Résultat du jour ?', o:['−2 500 USD', '+2 500 USD', '−500 USD', '−25 000 USD'], e:'Le vendeur perd quand le cours monte : (1,1500 − 1,1540) × 125 000 × 5 = −2 500 USD.', calc:'(1.1500-1.1540)*125000*5'},
{id:'q2-022', th:'Les marges', q:'Solde 8 437,5 ; perte du jour 6 937,5 ; maintenance 7 500 ; deposit 9 375. Solde après appel ?', o:['9 375 USD', '7 500 USD', '1 500 USD', '8 437,5 USD'], e:'Solde avant appel 1 500 &lt; 7 500 : appel de 7 875, le compte revient au deposit.'},
{id:'q2-023', th:'Les marges', q:'Valrhona : versé 16 000 + 10 000 USD, récupéré 19 000 USD à la liquidation. Résultat ?', o:['−7 000 USD', '+3 000 USD', '−10 000 USD', '+19 000 USD'], e:'Récupéré − versé = 19 000 − 26 000 = −7 000, comme (1,0860 − 1,1000) × 500 000.', calc:'19000-26000'},
{id:'q2-024', th:'Les marges', q:'Le deposit de Valrhona est de 4 000 USD par contrat pour 4 contrats. Deposit total ?', o:['16 000 USD', '4 000 USD', '12 000 USD', '1 000 USD'], e:'4 000 × 4 = 16 000 USD ; maintenance 75 % = 12 000 USD.', calc:'4000*4'},
{id:'q2-025', th:'Les marges', q:'Résultat cumulé d’une position = …', o:['solde final − total versé (deposit + appels)', 'solde final − deposit', 'somme des appels de marge', 'deposit − solde final'], e:'Contrôle de l’exercice 1 : 10 312,5 − 26 250 = −15 937,5 USD.'},

/* — Spéculation et trésorerie — */
{id:'q2-026', th:'Spéculation', q:'Un opérateur anticipe une appréciation de l’euro face au dollar. Que fait-il sur les Futures EUR/USD ?', o:['Il achète des contrats', 'Il vend des contrats', 'Il ne fait rien', 'Il achète et vend le même nombre'], e:'Appréciation de l’euro = hausse de EUR/USD : l’acheteur gagne.'},
{id:'q2-027', th:'Spéculation', q:'4 contrats EUR/USD achetés à 1,1000. Valeur notionnelle ?', o:['550 000 USD', '500 000 USD', '550 000 EUR', '137 500 USD'], e:'4 × 125 000 × 1,1000 = 550 000 USD.', calc:'4*125000*1.1'},
{id:'q2-029', th:'Spéculation', q:'Pourquoi une entreprise peut-elle manquer de trésorerie sur des Futures alors qu’elle anticipe un retournement favorable ?', o:['Les pertes sont réglées chaque jour par des appels de marge', 'Les gains ne sont versés qu’à l’échéance', 'Le deposit est rendu en fin de mois', 'La chambre prélève des commissions élevées'], e:'Le règlement est quotidien : faute de payer les appels, la position est liquidée et la perte devient définitive.'},
{id:'q2-030', th:'Spéculation', q:'Un spéculateur qui ne paie pas un appel de marge…', o:['voit sa position liquidée, la perte devient définitive', 'garde sa position jusqu’à l’échéance', 'reçoit un délai jusqu’au retournement', 'perd seulement l’appel non versé'], e:'La chambre se protège : la position est fermée.'},
{id:'q2-031', th:'Spéculation', q:'Valrhona : le cours passe de 1,0990 à 1,0800 pour 4 contrats achetés. Résultat du jour ?', o:['−9 500 USD', '+9 500 USD', '−2 375 USD', '−19 000 USD'], e:'(1,0800 − 1,0990) × 500 000 = −9 500 USD.', calc:'(1.0800-1.0990)*500000'},

/* — Sens de la couverture — */
{id:'q2-032', th:'Sens de la couverture', q:'Une société américaine a une créance de 1 M EUR. Que fait-elle sur les Futures EUR/USD ?', o:['Elle vend des contrats', 'Elle achète des contrats', 'Elle ne peut pas se couvrir', 'Elle vend des USD au comptant'], e:'Elle craint une baisse de l’EUR, donc de EUR/USD : position vendeuse.'},
{id:'q2-033', th:'Sens de la couverture', q:'Airbus (comptes en EUR) doit encaisser 2 500 000 USD. Sur les Futures EUR/USD, il…', o:['achète des contrats', 'vend des contrats', 'n’a pas de risque', 'achète des USD au comptant'], e:'Il craint une baisse de l’USD = hausse de EUR/USD : position acheteuse. Piège : « créance = vendre » ne vaut que si la créance est dans la devise du contrat.'},
{id:'q2-034', th:'Sens de la couverture', q:'Fender (comptes en USD) encaisse 1 250 000 GBP. Sur les Futures GBP/USD, il…', o:['vend des contrats', 'achète des contrats', 'achète des USD à terme', 'n’a pas de risque'], e:'Il craint une baisse de la livre : position vendeuse.'},
{id:'q2-035', th:'Sens de la couverture', q:'Une entreprise européenne doit payer des USD dans 3 mois. Sur les Futures EUR/USD, elle…', o:['vend des contrats', 'achète des contrats', 'ne peut pas se couvrir', 'achète et vend'], e:'Elle craint une hausse de l’USD, donc une baisse de EUR/USD : vendre.'},
{id:'q2-036', th:'Sens de la couverture', q:'Le principe d’une couverture par les Futures :', o:['prendre la position qui gagne quand la position physique perd', 'prendre la même position que la position physique', 'acheter toujours des contrats', 'vendre toujours des contrats'], e:'Le gain des Futures compense la perte sur le physique.'},
{id:'q2-037', th:'Sens de la couverture', q:'Une société américaine exportatrice, créance de 1 M EUR : quelle est la nature du risque ?', o:['Risque de change de transaction : baisse de l’EUR', 'Risque de taux d’intérêt', 'Risque de change : hausse de l’EUR', 'Risque de contrepartie seulement'], e:'Position longue en EUR : elle craint sa baisse.'},

/* — Nombre de contrats — */
{id:'q2-038', th:'Nombre de contrats', q:'1 250 000 GBP à couvrir, contrat de 62 500 GBP, correspondance des volumes. Nombre de contrats ?', o:['20', '17', '25', '16'], e:'1 250 000 ÷ 62 500 = 20.', calc:'1250000/62500'},
{id:'q2-039', th:'Nombre de contrats', q:'2 500 000 USD à couvrir, contrat de 125 000 EUR, F₀ = 1,0850. Nombre de contrats (volumes) ?', o:['18', '20', '19', '17'], e:'2 500 000 ÷ 1,0850 ÷ 125 000 ≈ 18,43, arrondi à 18.', eq:'N = #f{Q_{USD}}{F_{0} × T}', calc:'Math.round(2500000/1.085/125000)'},
{id:'q2-040', th:'Nombre de contrats', q:'Pour convertir un montant en USD en nombre de contrats EUR, on utilise…', o:['le cours du Future F₀', 'le cours au comptant de l’échéance', 'le cours le plus favorable', 'aucun cours : on divise par 125 000'], e:'La couverture est figée au cours du Future ; diviser des USD par 125 000 EUR mélange deux devises.'},
{id:'q2-041', th:'Nombre de contrats', q:'Ratio de couverture de variance minimale h* = …', o:['Cov(S, F) ÷ V(F)', 'V(F) ÷ Cov(S, F)', 'Cov(S, F) ÷ V(S)', 'σ_S ÷ σ_F'], e:'Covariance des variations du spot et du Future, divisée par la variance du Future.', eq:'h^{*} = #f{#t{Cov}(S, F)}{V(F)}'},
{id:'q2-042', th:'Nombre de contrats', q:'Cov(S, F) = 0,000085 et V(F) = 0,000100. h* ?', o:['0,85', '1,18', '0,085', '8,5'], e:'0,000085 ÷ 0,000100 = 0,85.', calc:'0.000085/0.0001'},
{id:'q2-043', th:'Nombre de contrats', q:'h* = 0,85, montant 1 250 000 GBP, contrat 62 500 GBP. Nombre de contrats (variance minimale) ?', o:['17', '20', '24', '23'], e:'0,85 × 1 250 000 ÷ 62 500 = 17.', eq:'N^{*} = h^{*} × #f{Q}{T}', calc:'0.85*1250000/62500'},
{id:'q2-044', th:'Nombre de contrats', q:'σ_S,F = 1,5 et σ²_F = 1,25 ; 1 000 000 EUR ; contrat 125 000 EUR. Nombre de contrats (variance minimale) ?', o:['10', '8', '7', '12'], e:'h* = 1,5 ÷ 1,25 = 1,2 ; 1,2 × 8 = 9,6, soit 10 contrats.', calc:'Math.round(1.5/1.25*1000000/125000)'},
{id:'q2-045', th:'Nombre de contrats', q:'« La société est totalement averse au risque » : quelle méthode pour le nombre de contrats ?', o:['La minimisation de la variance', 'La correspondance des volumes', 'Le plus petit nombre entier', 'Aucun contrat'], e:'Aversion totale + covariance et variance données = variance minimale (exercice 2).'},
{id:'q2-046', th:'Nombre de contrats', q:'h* &gt; 1 signifie…', o:['plus de contrats que par la correspondance des volumes', 'moins de contrats que par les volumes', 'aucune couverture nécessaire', 'une couverture parfaite'], e:'Ex. 2 : h* = 1,2, 10 contrats au lieu de 8.'},
{id:'q2-047', th:'Nombre de contrats', q:'18,43 contrats calculés : 18 contrats donnent…', o:['une légère sous-couverture', 'une sur-couverture', 'une couverture parfaite', 'une position spéculative à la baisse'], e:'On couvre un peu moins que l’exposition. 19 contrats donneraient une sur-couverture.'},
{id:'q2-048', th:'Nombre de contrats', q:'Arrondir 18,43 à 19 contrats revient à…', o:['prendre un petit pari en plus de la couverture', 'couvrir moins', 'supprimer le risque de base', 'réduire le deposit'], e:'Le contrat en trop est spéculatif : il gagne ou perd selon le sens du cours.'},

/* — Résultats de la couverture — */
{id:'q2-049', th:'Résultat de la couverture', q:'Société américaine, créance de 1 000 000 EUR, spot 1,25 puis 1,20. Résultat physique ?', o:['−50 000 USD', '+50 000 USD', '−40 000 EUR', '−5 000 USD'], e:'1 000 000 × (1,20 − 1,25) = −50 000 USD.', eq:'R_{P} = Q × (S_{t} − S_{0})', calc:'1e6*(1.2-1.25)'},
{id:'q2-050', th:'Résultat de la couverture', q:'Vendeur de 10 contrats EUR/USD : F₀ = 1,242322, F₁ = 1,199751. Résultat des Futures (à l’USD près) ?', o:['+53 214 USD', '−53 214 USD', '+5 321 USD', '+42 571 USD'], e:'10 × 125 000 × (1,242322 − 1,199751) ≈ +53 214 USD.', calc:'10*125000*(1.242322-1.199751)'},
{id:'q2-051', th:'Résultat de la couverture', q:'Résultat global = …', o:['résultat physique + résultat des Futures, dans la même monnaie', 'résultat des Futures seul', 'résultat physique − résultat des Futures', 'deposit + appels de marge'], e:'On additionne les deux jambes, exprimées dans la monnaie nationale.'},
{id:'q2-052', th:'Résultat de la couverture', q:'Airbus (comptes en EUR) gagne 87 750 USD sur ses Futures ; spot du jour 1,12. Comment l’intégrer au résultat global ?', o:['Le convertir au spot du jour de liquidation : 87 750 ÷ 1,12', 'L’ajouter tel quel en USD', 'Le convertir au cours F₀', 'Le convertir au spot initial S₀'], e:'TD, exercice 3 : le gain des Futures est converti en euros au spot du 30 septembre.',},
{id:'q2-053', th:'Résultat de la couverture', q:'Airbus, créance 2 500 000 USD, S₀ = 1,08, S_t = 1,12. Résultat physique en EUR (à l’euro près) ?', o:['−82 672 EUR', '+82 672 EUR', '−100 000 EUR', '−92 593 EUR'], e:'2 500 000 ÷ 1,12 − 2 500 000 ÷ 1,08 ≈ −82 672 EUR.', eq:'R_{P} = #f{Q_{USD}}{S_{t}} − #f{Q_{USD}}{S_{0}}', calc:'2500000/1.12-2500000/1.08'},
{id:'q2-054', th:'Résultat de la couverture', q:'Acheteur de 18 contrats EUR/USD : F₀ = 1,0850, F_t = 1,1240. Résultat des Futures ?', o:['+87 750 USD', '−87 750 USD', '+70 200 USD', '+8 775 USD'], e:'18 × 125 000 × 0,0390 = +87 750 USD.', calc:'18*125000*(1.1240-1.0850)'},
{id:'q2-055', th:'Résultat de la couverture', q:'Fender : physique −62 500 USD, 20 contrats vendus, F₀ = 1,2650, F_t = 1,2160. Résultat global ?', o:['−1 250 USD', '+61 250 USD', '−123 750 USD', '+1 250 USD'], e:'Futures : 20 × 62 500 × 0,0490 = +61 250 ; global : −62 500 + 61 250 = −1 250 USD.', calc:'-62500+20*62500*(1.265-1.216)'},
{id:'q2-056', th:'Résultat de la couverture', q:'Une couverture « parfaite » donne un résultat global…', o:['nul', 'égal au résultat physique', 'égal au deposit', 'toujours positif'], e:'Le gain d’une jambe compense exactement la perte de l’autre.'},
{id:'q2-057', th:'Résultat de la couverture', q:'Vendeur de 17 contrats GBP (62 500), F₀ = 1,2650, physique −62 500 USD. Quel F_t donne un résultat global nul ?', o:['≈ 1,2062', '≈ 1,3238', '≈ 1,2160', '≈ 1,2600'], e:'17 × 62 500 × (1,2650 − F_t) = 62 500, d’où F_t = 1,2650 − 1/17 ≈ 1,2062.', eq:'F_{t} = F_{0} − #f{R_{#t{visé}} − R_{P}}{N × T}', calc:'1.265-62500/(17*62500)'},

/* — Base et risques de la couverture (§ 3.3.4) — */
{id:'q2-058', th:'La base', q:'La base est définie par…', o:['b = S − F', 'b = F − S', 'b = F ÷ S', 'b = S + F'], e:'Spot moins Future, à une même date.'},
{id:'q2-059', th:'La base', q:'S₀ = 1,2600 et F₀ = 1,2650. Base initiale ?', o:['−0,0050', '+0,0050', '−0,0500', '2,5250'], e:'1,2600 − 1,2650 = −0,0050.', calc:'1.26-1.265'},
{id:'q2-060', th:'La base', q:'Couverture vendeuse à volumes égaux : le résultat global vaut…', o:['Q × (b_t − b₀)', 'Q × (b₀ − b_t)', 'Q × b_t', 'N × T × b₀'], e:'Tout le résultat vient de la variation de la base. Couverture acheteuse : signe opposé.', eq:'R_{G} = Q × (b_{t} − b_{0})'},
{id:'q2-061', th:'La base', q:'Fender : b₀ = −0,0050, b_t = −0,0060, Q = 1 250 000 GBP, couverture vendeuse. Résultat global ?', o:['−1 250 USD', '+1 250 USD', '−12 500 USD', '−125 USD'], e:'1 250 000 × (−0,0060 + 0,0050) = −1 250 USD.', calc:'1250000*(-0.006+0.005)'},
{id:'q2-062', th:'Risques de la couverture', q:'D’où vient le risque de base ?', o:['On liquide la couverture avant l’échéance du Future, quand spot et Future n’ont pas encore convergé', 'Du choix d’un nombre de contrats entier', 'D’une erreur de sens de la couverture', 'Du défaut de la chambre de compensation'], e:'§ 3.3.4 : l’échéance E est choisie après la date de liquidation t (E &gt; t) ; spot et Future ne convergent qu’à l’échéance.'},
{id:'q2-063', th:'Risques de la couverture', q:'Pourquoi l’opérateur choisit-il une échéance du Future postérieure à sa date de paiement (E &gt; t) ?', o:['Pour pouvoir déboucler sa position avant l’échéance du contrat', 'Pour payer un deposit plus faible', 'Parce que la base est nulle avant l’échéance', 'Pour éviter les appels de marge'], e:'Il doit être encore couvert le jour du paiement : il prend une échéance plus lointaine et liquide avant.'},
{id:'q2-064', th:'Risques de la couverture', q:'À l’échéance du contrat Future, la base est…', o:['nulle : spot et Future convergent', 'égale à la base initiale', 'égale au tick', 'maximale'], e:'Spot et Future ne convergent qu’à l’échéance ; avant, ils évoluent différemment.'},
{id:'q2-065', th:'Risques de la couverture', q:'Les risques résiduels d’une couverture par les Futures viennent notamment…', o:['de la quantité à couvrir qui n’est pas un multiple de la taille du contrat', 'de l’absence de chambre de compensation', 'du risque de contrepartie du courtier', 'de la cotation au certain'], e:'§ 3.3.4 : on couvre forcément par excès ou par défaut.'},
{id:'q2-066', th:'Risques de la couverture', q:'Airbus perd 4 323,74 EUR malgré sa couverture. Les deux sources de ce résultat :', o:['le risque de base et l’arrondi du nombre de contrats', 'le deposit et les appels de marge', 'le sens de la couverture et le levier', 'la commission et le spread'], e:'Base de −0,0050 à −0,0040 (le Future a moins monté que le spot) et 18 contrats au lieu de 18,43.'},
{id:'q2-067', th:'Risques de la couverture', q:'Un opérateur constate que le spot évolue en sa faveur et que le Future diverge. D’après le cours, il peut…', o:['liquider sa position Futures avant l’échéance pour limiter les pertes', 'doubler sa position', 'exiger le remboursement du deposit', 'rien : la position est bloquée jusqu’à l’échéance'], e:'§ 3.3.4 : il peut dénouer avant l’échéance et profiter du gain sur le spot.'},
{id:'q2-068', th:'Risques de la couverture', q:'« Notre modèle statistique est mauvais, il fallait 20 contrats et non 17 », dit un directeur après une seule période. Conclusion ?', o:['Non justifiée : le ratio minimise la dispersion en moyenne, pas dans chaque scénario', 'Justifiée : 20 contrats ont mieux fait', 'Justifiée : h* doit toujours valoir 1', 'Non justifiée : il fallait 0 contrat'], e:'Jugement a posteriori sur une seule réalisation des cours.'},

/* — F et f (§ 3.3.4) — */
{id:'q2-069', th:'Évaluer un Future', q:'Pour évaluer un Future, à quoi compare-t-on son cours F ?', o:['Au cours forward théorique f de même échéance', 'Au cours au comptant S', 'Au deposit', 'Au cours de compensation de la veille'], e:'§ 3.3.4 : comparaison de F et du forward théorique f pour une échéance n = E − t.'},
{id:'q2-070', th:'Évaluer un Future', q:'F &gt; f : le Future est…', o:['surévalué : on le vend', 'sous-évalué : on l’achète', 'à son juste prix', 'surévalué : on l’achète'], e:'Surévalué = trop cher : on le vend et on fabrique l’opération inverse au cours théorique.'},
{id:'q2-071', th:'Évaluer un Future', q:'F &lt; f : le Future est…', o:['sous-évalué', 'surévalué', 'à son juste prix', 'impossible à évaluer'], e:'Moins cher que sa valeur théorique : on l’achète.'},
{id:'q2-072', th:'Évaluer un Future', q:'Spot EUR/USD 1,25 ; taux USD 2,25 % et EUR 3,5 % à 6 mois. Cours théorique f (4 décimales) ?', o:['1,2423', '1,2578', '1,2500', '1,2344'], e:'1,25 × (1 + 2,25 % × 6/12) ÷ (1 + 3,5 % × 6/12) ≈ 1,2423. Taux USD au numérateur.', eq:'f = S × #f{1 + i_{USD} × #f{n}{12}}{1 + i_{EUR} × #f{n}{12}}', calc:'1.25*(1+0.0225/2)/(1+0.035/2)'},
{id:'q2-073', th:'Évaluer un Future', q:'Dans la parité des taux EUR/USD, quel taux est au numérateur ?', o:['Le taux de l’USD (monnaie de cotation)', 'Le taux de l’EUR', 'Le plus élevé des deux', 'La différence des deux'], e:'f = S × (1 + i_USD × n/12) ÷ (1 + i_EUR × n/12).'},
{id:'q2-074', th:'Évaluer un Future', q:'Pour estimer F au 31/05 avec un contrat d’échéance fin juin, on prend…', o:['les taux à 1 mois (n = 1)', 'les taux à 6 mois', 'les taux à 5 mois', 'aucun taux : F = S'], e:'On compte jusqu’à l’échéance du contrat (juin), pas jusqu’au paiement : n = E − t = 1 mois.'}
]
};
